int bin_search(int *arr, int len, int target) {
    int l = 0;
    int r = len - 1;
    int mid = (l + r) / 2;
    while(l <= r) {
        //Found:
        if(arr[mid] == target) return mid;
        //Num too big:
        else if(arr[mid] > target) r = mid; 
        //Num too small:
        else l = mid + 1;
        //Reset mid with new left and right pointers.
        mid = (l + r) / 2;
    }
    //-1 means element not found.
    return -1;
}
```

