async function copy(src: string, destination: string): Promise<void> {
    const stat = await promises.stat(src); // Get status of source, copy from here.

    if (stat.isDirectory()) { // Source is directory:
        const contained = await promises.readdir(src); // Read what inside directory.
        await Promise.all( // Wait for all promises to finish.
            contained.map((file) => copy(join(src, file), join(destination, file))) // Copy each file in directory to destination.
